(27494, 721, 810, 2, 0, 'DESARROLLA HABILIDADES  DE MOTRICIDAD FINA Y GRUESA, DIBUJA Y PINTA  FIGURAS GEOMÉTRICAS, RECONOCE Y DIBUJA LAS PARTES DEL CUERPO HUMANO, PRACTICA LA HONESTIDAD COMO VALOR FUNDAMENTAL. LIMITACIÓN AL MOMENTO DE REALIZAR TAREAS EN EL AULA SE DISTRAE MUCHO DEMOSTRANDO DESOBEDIENCIA.'),
(27495, 722, 810, 2, 0, 'ASUME LOS VALORES QUE  PRACTICAN EN SU FAMILIA Y COMUNIDAD DEMUESTRA SER COLABORATIVO CON SUS COMPAÑEROS Y  SE ADVIERTEN LIMITACIONES PARA COMPRENDER Y RECONOCER CANTIDAD Y NÚMERO EN OBJETOS DEL ENTORNO  ASÍ  MISMO   DIFICULTAD AL RECONOCER LAS VOCALES EN DIFERENTES TEXTOS.'),
(27496, 723, 810, 2, 0, 'SUME LOS VALORES QUE SE PRACTICAN EN SU FAMILIA Y COMUNIDAD Y  SE ADVIERTEN LIMITACIONES PARA COMPRENDER LOS CONTENIDOS DESARROLLADOS EN MATEMÁTICA TALES COMO LAS FIGURAS GEOMÉTRICAS Y LATERALIDAD IZQUIERDA Y DERECHA, DIFICULTAD  PARA TOMAR DECISIONES.'),
(27500, 724, 810, 2, 0, 'DESARROLLA  HABILIDADES Y DESTREZAS DE MANERA CREATIVA, ESCRIBE SU NOMBRE Y APELLIDO TAMBIÉN IDENTIFICA VOCALES EN DIFERENTES TEXTOS    ASÍ MISMO DEMUESTRA EL VALOR DE LA SOLIDARIDAD CON SUS COMPAÑEROS EN LA ESCUELA Y LA COMUNIDAD, PARTICIPA  EN LA PRÁCTICA DE LOS SABERES Y CONOCIMIENTOS DE LA VIDA.'),
(27513, 725, 810, 2, 0, 'MANIFIESTA RESPETO Y RECIPROCIDAD CON SUS COMPAÑEROS DE CURSO, RECONOCE VOCALES Y USA NÚMEROS ORDINALES EN LOS JUEGOS NO DIRIGIDOS,  PARTICIPA EN EL MANEJO APROPIADO DE TIJERA AL REALIZAR RECORTES DE  FIGURAS.  LIMITACIÓN AL MOMENTO DE  EXPRESAR SUS IDEAS'),
(27514, 726, 810, 2, 0, 'ACTITUD Y COMPORTAMIENTO ADECUADO EN LAS INTERACCIONES SOCIALES.   IDENTIFICACIÓN DE ROLES DE CADA UNO DE LOS MIEMBROS DE SU FAMILIA.\r\nREPRESENTACIÓN GRÁFICA DE LOS INTEGRANTES DE SU FAMILIA,  ESCRIBE SU NOMBRE COMPLETO CON FACILIDAD, VALORA LAS ACTIVIDADES EN LAS QUE SE DEDICA SUS PADRES.'),
(27515, 727, 810, 2, 0, 'MANIFIESTA RESPETO Y RECIPROCIDAD CON SUS COMPAÑEROS DE CURSO, RECONOCE Y USA NÚMEROS ORDINALES EN LOS JUEGOS NO DIRIGIDOS,  PARTICIPA EN EL MANEJO APROPIADO DE TIJERA AL REALIZAR RECORTES DE DIFERENTES FIGURAS.  LIMITACIÓN AL MOMENTO DE  EXPRESAR SUS IDEAS.'),
(27516, 728, 810, 2, 0, 'PARTICIPA EN ACTIVIDADES MUSICALES Y DEPORTIVAS, REALIZA CONTEO DE NÚMEROS EN FORMA ORDENADA   NOMBRA E IDENTIFICA A LOS MIEMBROS DE SU FAMILIA,  DESARROLLA HABILIDADES Y DESTREZAS DE MANERA CREATIVA.    CUANDO JUEGA  JUEGOS NO DIRIGIDOS. ADVIERTE  LIMITACIÓN  DE DESOBEDIENCIA  AL MOMENTO DE REALIZAR TAREAS ASIGNADAS.'),
(27517, 729, 810, 2, 0, 'DESCRIBE LAS COSTUMBRES DE SU FAMILIA, SE EXPRESA CLARAMENTE, COMPARA FORMAS, GEOMÉTRICAS, IDENTIFICA  ELEMENTOS DE LA NATURALEZA LAS CUALES AYUDAN A CUIDAR A LA MADRE TIERRA, RESPETA LA DIVERSIDAD CULTURAL DE SU ENTORNO. LIMITACIÓN  AL PARTICIPAR EN JUEGOS RECREATIVOS.'),
(27518, 730, 810, 2, 0, 'MANIFIESTA RESPETO Y RECIPROCIDAD CON SUS COMPAÑEROS DE CURSO, RECONOCE Y USA NÚMEROS ORDINALES EN LOS JUEGOS. NO DIRIGIDOS. EXPRESA LAS NECESIDADES BÁSICAS DEL SER HUMANO PARTICIPA EN EL MANEJO APROPIADO DE TIJERA Y LIMITACIONES AL COMPARTIR SUS IDEAS DENTRO EL AULA.'),
(27519, 733, 810, 2, 0, 'MANIFIESTA RESPETO Y RECIPROCIDAD CON SUS COMPAÑEROS DE CURSO, RECONOCE Y USA NÚMEROS ORDINALES EN LOS JUEGOS. NO DIRIGIDOS. EXPRESA LAS NECESIDADES BÁSICAS DEL SER HUMANO PARTICIPA EN EL MANEJO APROPIADO DE TIJERA Y LIMITACIONES AL COMPARTIR SUS IDEAS DENTRO EL AULA.\r\n\r\nDESCRIBE LAS COSTUMBRES DE SU FAMILIA, SE EXPRESA CLARAMENTE, COMPARA FORMAS, Y CANTIDADES AL MOMENTO DE CONTAR, IDENTIFICA  ELEMENTOS DE LA NATURALEZA LAS CUALES AYUDAN A CUIDAR A LA MADRE TIERRA, RESPETA LA DIVERSIDAD CULTURAL DE SU ENTORNO, LE AGRADA DIBUJAR Y PINTAR CON COLORES DE SU PREFERENCIA.'),
(27520, 734, 810, 2, 0, 'RECONOCE LAS VOCALES EN DIFERENTES TEXTOS Y NÚMEROS ORDINALES EN LOS JUEGOS. NO DIRIGIDOS, EXPRESA LAS NECESIDADES BÁSICAS DEL SER HUMANO PARTICIPA EN EL MANEJO APROPIADO DE TIJERAS, DEMUESTRA MUCHA  INQUIETUD Y DESOBEDIENCIA AL REALIZAR   LAS TAREAS ASIGNADAS EN EL AULA.'),
(27521, 735, 810, 2, 0, 'DEMUESTRA INQUIETUD POR APRENDER, PRONUNCIA  SU NOMBRE COMPLETO EN LENGUAJE CLARO, RECONOCE LAS VOCALES EN DIFERENTES TEXTOS , CUENTA LOS NÚMEROS DEL 1 AL 20 CON FACILIDAD, VALORA LAS  ACTIVIDADES QUE REALIZAN EN SU FAMILIA, PARTICIPA EN RONDAS, CANCIONES Y ACTIVIDAD FÍSICA CON ENTUSIASMO.'),
(27522, 736, 810, 2, 0, 'DEMUESTRA INQUIETUD POR APRENDER, PRONUNCIA  SU NOMBRE COMPLETO EN LENGUAJE CLARO, RECONOCE LAS VOCALES EN DIFERENTES TEXTOS, CUENTA LOS NÚMEROS DEL 1 AL 20 CON FACILIDAD, VALORA LAS  ACTIVIDADES QUE REALIZAN EN SU FAMILIA, PARTICIPA EN RONDAS, CANCIONES Y ACTIVIDAD FÍSICA CON ENTUSIASMO.\r\n\r\nASUME LOS VALORES QUE SE PRACTICAN EN SU FAMILIA Y COMUNIDAD, COMPRENDE LOS CONTENIDOS DESARROLLADOS EN MATEMÁTICA  TALES COMO LAS FIGURAS GEOMÉTRICAS Y LATERALIDAD IZQUIERDA - DERECHA , RECONOCE LAS VOCALES EN DIFERENTES TEXTOS  Y PRONUNCIA PALABRAS INICIADAS EN VOCALES, PARTICIPA EN BAILES CON AGRADO.'),
(27523, 737, 810, 2, 0, 'DESARROLLA SUS HABILIDADES DE MANERA CREATIVA LE AGRADA MANIPULAR PLASTILINA FORMANDO ANIMALITOS DE SU AGRADO, REPITE  LAS VOCALES  CON AYUDA DE IMÁGENES, RECONOCE LOS NÚMEROS  CON AYUDA Y DEMUESTRA EN SUS DEDITOS,  COMUNICA SUS IDEAS EN LENGUAJE ORAL CLARO.'),
(27524, 738, 810, 2, 0, 'PARTICIPA EN ACTIVIDADES MUSICALES Y DEPORTIVAS  CON  AGRADO, REALIZA CONTEO DE NÚMEROS NATURALES EN FORMA DESORDENADA,  EXPRESA SUS IDEAS  CON SUS COMPAÑEROS  EN  LENGUAJE  ORAL  Y MÍMICA, LIMITACIÓN AL REALIZAR ACTIVIDADES ASIGNADAS EN EL CURSO DEMUESTRA DESOBEDIENCIA.'),
(27525, 739, 810, 2, 0, 'PARTICIPA EN ACTIVIDADES MUSICALES Y DEPORTIVAS  CON  AGRADO, REALIZA CONTEO DE NÚMEROS NATURALES EN FORMA DESORDENADA, ESCRIBE SU NOMBRE CON FACILIDAD,   EXPRESA SUS IDEAS  CON SUS COMPAÑEROS, REALIZA  DIBUJOS Y PINTA CON AGRADO.  LIMITACIÓN AL COMUNICAR SUS IDEAS A SU MAESTRA.'),
(27526, 740, 810, 2, 0, 'RECONOCE LAS PARTES DE SU CUERPO MOSTRANDO COORDINACIÓN MOTORA EN ACTIVIDADES FÍSICAS DE MOVIMIENTO COMO SALTAR, CORRER Y TREPAR, PARTICIPA   DE FORMA ESPONTÁNEA, PARTICIPA EN BAILES ,   LIMITACIONES AL MOMENTO DE REALIZAR ACTIVIDADES ASIGNADAS EN EL CURSO  TÍMIDO AL PARTICIPAR.'),
(27527, 742, 810, 2, 0, 'PARTICIPA EN RECONOCIMIENTO DE LAS VOCALES EN DIFERENTES TEXTOS, IDENTIFICA NOCIÓN COMPARATIVA GRANDE-PEQUEÑO, ESPACIALIDAD CEJOS-CERCA Y SU LATERALIDAD IZQUIERDA- DERECHA PARTICIPANDO EN CANCIÓN INFANTIL, PINTA  Y DIBUJA ADECUADAMENTE, A LOS MIEMBROS DE SU FAMILIA CONVERSA CON SUS COMPAÑEROS SUS EXPERIENCIAS VIVIDAS EN SU FAMILIA.'),
